fn file_values(path: &str) -> BTreeMap<String, String> {
    // `key = "value"` lines; anything else is ignored. Kept tiny on purpose.
    let mut out = BTreeMap::new();
    if let Ok(text) = std::fs::read_to_string(path) {
        for line in text.lines() {
            if let Some((k, v)) = line.split_once('=') {
                let k = k.trim();
                if !k.starts_with('#') && !k.is_empty() {
                    out.insert(k.to_string(), v.trim().trim_matches('"').to_string());
                }
            }
        }
    }
    out
}

/// The value of one declared setting: env `<PRODUCT>_<KEY>` (dots become underscores),
/// then the file, then the model default. A key the model does not declare is refused.
pub fn value(key: &str, file: &BTreeMap<String, String>) -> String {
    let Some((_, default)) = SETTINGS.iter().find(|(k, _)| *k == key) else {
        panic!("setting '{key}' is not declared in the model for {PRODUCT}");
    };
    let env = format!("{}_{}", PRODUCT.to_uppercase(), key.to_uppercase().replace(['.', '-'], "_"));
    std::env::var(&env).ok().or_else(|| file.get(key).cloned()).unwrap_or_else(|| default.to_string())
}

